BEGIN;

DELETE FROM customers a
 USING customers b
 WHERE a.email = b.email
   AND a.customer_id > b.customer_id
RETURNING a.customer_id, a.email;

BEGIN;

DELETE FROM payment_import a
 USING payment_import b
 WHERE a.payment_ref = b.payment_ref
   AND a.order_no    = b.order_no
   AND a.amount      = b.amount
   AND a.paid_via    = b.paid_via
   AND a.ctid > b.ctid;

ROLLBACK;

BEGIN;

CREATE TEMP TABLE payment_dedup AS
SELECT DISTINCT * FROM payment_import;

TRUNCATE payment_import;

INSERT INTO payment_import SELECT * FROM payment_dedup;

COMMIT;

ALTER TABLE customers ADD CONSTRAINT customers_email_key UNIQUE (email);

